import json

with open('/Users/marcel.a.n.navarro/.claude/projects/-Users-marcel-a-n-navarro-Dev/55897b36-2e8a-4de7-9e00-42810c8ba75c.jsonl') as f:
    lines = f.readlines()

# Find assistant messages
for i, line in enumerate(lines):
    try:
        obj = json.loads(line)
        if obj.get('type') == 'assistant':
            msg = obj.get('message', {})
            content = msg.get('content', [])
            for block in content:
                if isinstance(block, dict) and block.get('type') == 'text':
                    text = block.get('text', '')
                    if 'two-layer' in text or 'as-built' in text or 'Revised description' in text or 'New description' in text:
                        print(f'=== LINE {i} ===')
                        print(text[:300])
                        print('...')
    except:
        pass
"
